), checked AS (
SELECT e.question_id,
 q.id IS NOT NULL AND school_category_private.question_revision(q.id)=e.question_revision
 AND q.source_id=e.source_id AND md5(to_jsonb(s)::text)=e.source_revision
 AND q.license_id=e.license_id AND md5(to_jsonb(l)::text)=e.license_revision
 AND q.publication_status='PUBLICADO' AND q.workflow_status='APROVADO' AND q.curation_status='HOMOLOGADO'
 AND q.school_year='2o ano' AND q.component IN ('Lingua Portuguesa','Matematica')
 AND s.curation_status='HOMOLOGADO' AND l.publication_allowed
 AND NOT EXISTS(SELECT 1 FROM public.content_question_items a WHERE a.question_item_id=q.id) AS snapshot_matches
 FROM expected e LEFT JOIN public.question_items q ON q.id=e.question_id
 LEFT JOIN public.question_sources s ON s.id=q.source_id LEFT JOIN public.question_licenses l ON l.id=q.license_id)
SELECT count(*) expected_count,count(*) FILTER(WHERE snapshot_matches) matching_count,
 count(*)=202 AND bool_and(coalesce(snapshot_matches,false)) snapshot_guard_pass,
 'REVIEW PACKAGE: authorship confirmed; limited editorial conversion and resolver patches require artifact review' AS publication_gate FROM checked;

